// KONTEXT: Prüft das KI-Ergebnis, zwingt den Score in den Bereich der Kategorie, entfernt Personendaten aus den KI-Texten und baut die Felder für Airtable, Telegram und Dossier.
// BEISPIEL: Die KI meldet hot mit Score 55 und schreibt "Herr Meier braucht Hilfe". Ergebnis: hot mit Score 70 und "die Person braucht Hilfe".

// ---------- ABSCHNITT 1: Konstanten ----------
// „Jede Kategorie legt Score-Bereich, Priorität und Status in Airtable fest.“
const KATEGORIEN = {
  hot:  { min: 70, max: 100, prioritaet: 'Hoch',    status: 'Qualifiziert' },
  warm: { min: 40, max: 69,  prioritaet: 'Mittel',  status: 'Qualifiziert' },
  kalt: { min: 1,  max: 39,  prioritaet: 'Niedrig', status: 'Unqualifiziert' },
  spam: { min: 0,  max: 0,   prioritaet: 'Niedrig', status: 'Unqualifiziert' },
  rueckfrage: { min: 10, max: 39, prioritaet: 'Mittel', status: 'Rückfrage' },
};
// „Eine unklare KI-Antwort behandeln wir vorsichtig als warm, damit kein Lead verloren geht.“
const FALLBACK_KATEGORIE = 'warm';
// „Aus dem Umsatzband machen wir einen kurzen Satz für Telegram.“
const GROESSE_TEXT = { 'über 50 Mio. €': 'sehr hoher Jahresumsatz', '10 bis 50 Mio. €': 'hoher Jahresumsatz', '1 bis 10 Mio. €': 'mittlerer Jahresumsatz', 'unter 1 Mio. €': 'kleiner Jahresumsatz' };

// ---------- ABSCHNITT 2: Hilfsfunktionen ----------
// „Diese Funktion entfernt E-Mails, Telefonnummern und Namen aus einem Text.“
const anonym = (text, namen) => {
  // „Wir starten mit dem Text als Zeichenkette.“
  let t = String(text || '');
  // „E-Mail-Adressen werden ersetzt.“
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[E-Mail]');
  // „Telefonnummern werden ersetzt.“
  t = t.replace(/(\+49|0)[0-9][0-9\/\s-]{5,}[0-9]/g, '[Telefon]');
  // „Jeder Namensteil mit mindestens 3 Buchstaben wird als ganzes Wort durch die Person ersetzt.“
  namen.map((n) => String(n || '').replace(/[^\p{L}]/gu, '')).filter((n) => n.length >= 3).forEach((n) => { t = t.replace(new RegExp('(?<![\\p{L}])' + n + '(?![\\p{L}])', 'gu'), 'die Person'); });
  // „Wir geben den bereinigten Text zurück.“
  return t;
};
// „Diese Funktion macht Text HTML-sicher für Telegram.“
const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---------- ABSCHNITT 3: KI-Ergebnis prüfen und aufbereiten ----------
// „Für jedes Ergebnis holen wir den Lead und bauen die Felder.“
return $input.all().map((item, index) => {
  // „Das KI-Ergebnis steckt im Feld output.“
  const ki = item.json.output || {};
  // „Den Lead holen wir über die Zuordnung, sonst über denselben Index.“
  let lead;
  try {
    lead = $('check_lead').itemMatching(index).json;
  } catch (e) {
    lead = $('check_lead').all()[index].json;
  }
  // „Wenn die KI-Kategorie unbekannt ist, nehmen wir den Fallback.“
  const kategorie = KATEGORIEN[ki.kategorie] ? ki.kategorie : FALLBACK_KATEGORIE;
  // „Wir holen die Regeln dieser Kategorie.“
  const regel = KATEGORIEN[kategorie];
  // „Wir runden den Score der KI auf eine ganze Zahl.“
  const rohScore = Math.round(Number(ki.score));
  // „Wir zwingen den Score in den Bereich der Kategorie.“
  const score = Number.isFinite(rohScore) ? Math.min(regel.max, Math.max(regel.min, rohScore)) : regel.min;
  // „Der Name der KI hat Vorrang, weil Absendernamen in Mails oft ungenau sind.“
  const name = ki.name || lead.name;
  // „Alle Namensteile merken wir uns für die Bereinigung.“
  const namen = (lead.name + ' ' + (ki.name || '')).split(/\s+/);
  // „Die Begründung der KI wird von Personendaten befreit.“
  const reasoning = anonym(ki.begruendung, namen);
  // „Die Rechercheangaben setzen wir zu einem Text für Airtable zusammen.“
  const recherche = ['Firma real: ' + (ki.firmaReal || 'unklar'), 'Umsatz: ' + (ki.umsatzBand || 'keine Zahlen') + (ki.zahlenJahr ? ' (' + ki.zahlenJahr + ', ' + (ki.zahlenQuelle || '') + ')' : ''), 'Mitarbeitende: ' + (ki.mitarbeiterBand || 'keine Zahlen'), anonym(ki.recherche, namen)].filter(Boolean).join(' | ');
  // „Wir geben den fertigen Datensatz weiter.“
  return {
    json: {
      name,
      email: lead.email,
      telefon: lead.telefon || ki.telefon || '',
      unternehmen: lead.firma || ki.firma || '',
      nachricht: lead.nachricht,
      datum: lead.datum,
      quelle: lead.quelle,
      kategorie,
      score,
      prioritaet: regel.prioritaet,
      status: regel.status,
      kiReasoning: reasoning,
      kiReasoningHtml: esc(reasoning),
      kiRecherche: recherche,
      antwortEntwurf: ki.antwortEntwurf || '',
      angebot: anonym(ki.angebot, namen),
      redFlags: (ki.redFlags || []).map((f) => anonym(f, namen)),
      firmaReal: ki.firmaReal || '',
      umsatzBand: ki.umsatzBand || '',
      mitarbeiterBand: ki.mitarbeiterBand || '',
      groesseKurz: GROESSE_TEXT[ki.umsatzBand] || (ki.mitarbeiterBand ? 'Mitarbeitende: ' + esc(ki.mitarbeiterBand) : 'Größe unbekannt'),
    },
    pairedItem: { item: index },
  };
});

// ===== Abschnitt 1: Konstanten =====
// Freemail-Anbieter: Absender ist eher eine Privatperson als eine Firma
const FREEMAIL_DOMAINS = ['gmail.com', 'googlemail.com', 'web.de', 'gmx.de', 'gmx.net', 't-online.de', 'outlook.com', 'outlook.de', 'hotmail.com', 'hotmail.de', 'yahoo.com', 'yahoo.de', 'icloud.com', 'freenet.de'];
// Nur fast leere Nachrichten gelten als Spam-Verdacht (kurze echte Anfragen wie "Brauche Hilfe" gehen zur KI)
const MIN_NACHRICHT_LAENGE = 5;
// Mehr Links in der Nachricht gelten als Spam-Verdacht
const MAX_LINKS = 3;
// Automatische Absender bekommen keine Antwort-Mail (verhindert Mail-Schleifen)
const AUTOMATISCHE_ABSENDER = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|newsletter)/i;
// Eigene Absenderadresse (auch mit Plus-Zusatz): Mails von uns selbst sind nie Anfragen, sonst füttert sich der Workflow mit seinen eigenen Antworten
const EIGENE_ADRESSE = /^your\.address(\+[^@\s]*)?@example\.com$/;

// ===== Abschnitt 2: Lead normalisieren und auf Spam-Verdacht prüfen =====
return $input.all().map((item, index) => {
  const lead = item.json;
  const email = String(lead.email || '').toLowerCase().trim();
  const domain = email.split('@')[1] || '';
  const nachricht = String(lead.nachricht || '').trim();
  const anzahlLinks = (nachricht.match(/https?:\/\//gi) || []).length;

  const gruende = [];
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) gruende.push('ungültige E-Mail-Adresse');
  if (AUTOMATISCHE_ABSENDER.test(email)) gruende.push('automatischer Absender');
  if (EIGENE_ADRESSE.test(email)) gruende.push('eigene Absenderadresse (Mail-Schleife)');
  if (nachricht.length < MIN_NACHRICHT_LAENGE) gruende.push('Nachricht zu kurz');
  if (anzahlLinks > MAX_LINKS) gruende.push('zu viele Links');

  return {
    json: {
      ...lead,
      email,
      domain,
      istFreemail: FREEMAIL_DOMAINS.includes(domain),
      spamVerdacht: gruende.length > 0,
      spamGrund: gruende.length > 0 ? 'Vorfilter: ' + gruende.join(', ') : '',
    },
    pairedItem: { item: index },
  };
});

