// KONTEXT: Baut aus dem Ergebnis eine kleine HTML-Datei (Dossier) für den Hot Lead, die du per Mail bekommst und im Browser öffnest. Sie enthält keine Kontaktdaten.
// BEISPIEL: Hot Lead mit Score 82, Umsatzband "10 bis 50 Mio. €" und 1 Red Flag ergibt lead-dossier.html mit Kennzahlen, Red Flag und Link zum Airtable-Datensatz.

// ---------- ABSCHNITT 1: Konstanten ----------
// „Das ist die Adresse der Airtable-Tabelle, an die wir die Datensatz-ID hängen.“
const BASIS_LINK = 'https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_AIRTABLE_TABLE_ID/';

// ---------- ABSCHNITT 2: Hilfsfunktion ----------
// „Diese Funktion macht Text HTML-sicher, damit nichts den Aufbau stört.“
const esc = (t) => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// ---------- ABSCHNITT 3: Pro Lead ein Dossier bauen ----------
// „Wir sammeln die fertigen Dossiers in dieser Liste.“
const ergebnis = [];
// „Für jeden Lead dieses Laufs bauen wir ein eigenes Dossier.“
for (const [index, item] of $input.all().entries()) {
  // „Wir holen die aufbereiteten Daten dieses Leads.“
  const d = $('process_ai_output').all()[index].json;
  // „Wir bauen den Link zum Datensatz aus der Datensatz-ID.“
  const link = BASIS_LINK + item.json.id;
  // „Die Red Flags machen wir zu Listenpunkten oder zu einem Hinweis, dass es keine gibt.“
  const flags = (d.redFlags && d.redFlags.length) ? d.redFlags.map((f) => '<li>' + esc(f) + '</li>').join('') : '<li class="ok">keine Auffälligkeiten</li>';
  // „Jetzt setzen wir die Seite aus Kopf, Kennzahlen und Abschnitten zusammen.“
  const html = [
    // „Der Kopf mit dunklem Design.“
    '<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Lead-Dossier</title><style>body{background:#121214;color:#E7E7EA;font-family:Segoe UI,Arial,sans-serif;max-width:720px;margin:32px auto;padding:0 16px}h1{color:#5FE3C0;font-weight:600}h2{color:#5FE3C0;font-size:15px;margin:24px 0 6px}.k{display:flex;gap:12px;flex-wrap:wrap}.k div{background:#1c1c20;border-radius:10px;padding:12px 16px;min-width:140px}.k b{display:block;font-size:22px;color:#5FE3C0}.k span{color:#9A9AA2;font-size:12px}li{margin:4px 0}.ok{color:#9A9AA2}.red li{color:#FF6D5A}a{color:#5FE3C0}small{color:#9A9AA2}</style></head><body>',
    // „Die Überschrift mit der Kategorie.“
    '<h1>Lead-Dossier: ' + esc(d.kategorie) + '</h1>',
    // „Vier Kennzahlen als Kacheln.“
    '<div class="k"><div><b>' + esc(d.score) + '</b><span>Score</span></div><div><b>' + esc(d.umsatzBand || 'unbekannt') + '</b><span>Jahresumsatz (Band)</span></div><div><b>' + esc(d.mitarbeiterBand || 'unbekannt') + '</b><span>Mitarbeitende (Band)</span></div><div><b>' + esc(d.firmaReal || 'unklar') + '</b><span>Reale Firma</span></div></div>',
    // „Was die Firma macht.“
    '<h2>Was die Firma macht</h2><p>' + esc(d.unternehmen || 'unbekannt') + (d.angebot ? ': ' + esc(d.angebot) : '') + '</p>',
    // „Warum der Lead so bewertet wurde.“
    '<h2>Warum diese Bewertung</h2><p>' + esc(d.kiReasoning) + '</p>',
    // „Das Ergebnis der Recherche.“
    '<h2>Recherche</h2><p>' + esc(d.kiRecherche) + '</p>',
    // „Die Red Flags in Koralle.“
    '<h2>Red Flags</h2><ul class="red">' + flags + '</ul>',
    // „Der Link zum Datensatz mit allen Kontaktdaten.“
    '<h2>Kontakt und Anfrage</h2><p><a href="' + link + '">Hier geht’s zum Lead</a></p>',
    // „Der Hinweis zur Herkunft der Zahlen.“
    '<p><small>Automatisch erstellt. Zahlen nur als Bänder aus öffentlichen Quellen, ohne Gewähr.</small></p></body></html>',
  ].join('');
  // „Wir machen aus dem Text eine Datei, die an die Mail angehängt werden kann.“
  const datei = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'lead-dossier.html', 'text/html');
  // „Wir legen Datei und Score in die Liste.“
  ergebnis.push({ json: { score: d.score }, binary: { dossier: datei }, pairedItem: { item: index } });
}
// „Wir geben alle Dossiers zurück.“
return ergebnis;
